#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RULES_FILE="${PDALINK_UDEV_RULES_FILE:-/etc/udev/rules.d/51-pdalink-android-aoa.rules}"
DRY_RUN=0
RELOAD=1

usage() {
  cat <<EOF
Usage: sudo $0 [--rules-file PATH] [--dry-run] [--no-reload]

Installs Linux udev rules for PdaLink Android USB access.

Managed IDs:
  Samsung Android ADB/RNDIS: 04e8:6860, 04e8:6864
  Google AOA product USB:   18d1:2d01
EOF
}

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

rules_content() {
  cat <<'EOF'
# PdaLink Android USB access rules.
# Generated by tools/install_linux_udev.sh.
#
# Samsung phones can expose different product IDs as USB mode changes. Keep the
# known ADB/RNDIS IDs together so a mode switch does not silently break ADB.
SUBSYSTEM=="usb", ATTR{idVendor}=="04e8", ATTR{idProduct}=="6860", MODE="0664", GROUP="plugdev", TAG+="uaccess"
SUBSYSTEM=="usb", ATTR{idVendor}=="04e8", ATTR{idProduct}=="6864", MODE="0664", GROUP="plugdev", TAG+="uaccess"

# Google Android Open Accessory mode used by the product USB bridge.
SUBSYSTEM=="usb", ATTR{idVendor}=="18d1", ATTR{idProduct}=="2d01", MODE="0664", GROUP="plugdev", TAG+="uaccess"
EOF
}

print_recovery_steps() {
  cat <<EOF

Recovery check:
  ./tools/adb.sh kill-server
  ./tools/adb.sh devices -l
  ./tools/pdalink.sh usb status

If ADB still reports no permissions, unplug and reconnect the phone so udev can
apply the refreshed rules to the new USB device node.
EOF
}

install_rules() {
  if [[ "$DRY_RUN" -eq 1 ]]; then
    echo "DRY-RUN write $RULES_FILE"
    rules_content
  else
    if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
      fail "run this installer with sudo, or use --dry-run to inspect the rules"
    fi
    local tmp
    tmp="$(mktemp)"
    rules_content >"$tmp"
    install -m 0644 -o root -g root "$tmp" "$RULES_FILE"
    rm -f "$tmp"
    echo "Installed PdaLink udev rules: $RULES_FILE"
  fi
}

reload_rules() {
  if [[ "$RELOAD" -eq 0 ]]; then
    if [[ "$DRY_RUN" -eq 1 ]]; then
      echo "DRY-RUN skip udevadm control --reload-rules"
      echo "DRY-RUN skip udevadm trigger --subsystem-match=usb"
    else
      echo "Skipped udev reload."
    fi
    return
  fi

  if [[ "$DRY_RUN" -eq 1 ]]; then
    echo "DRY-RUN udevadm control --reload-rules"
    echo "DRY-RUN udevadm trigger --subsystem-match=usb"
  else
    udevadm control --reload-rules
    udevadm trigger --subsystem-match=usb
    echo "Reloaded udev rules."
  fi
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --rules-file)
      RULES_FILE="${2:-}"
      [[ -n "$RULES_FILE" ]] || fail "--rules-file requires a value"
      shift 2
      ;;
    --dry-run)
      DRY_RUN=1
      shift
      ;;
    --no-reload)
      RELOAD=0
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      usage >&2
      exit 2
      ;;
  esac
done

install_rules
reload_rules
print_recovery_steps
